<?php

/**
 * Hand-written code. NOT generated by Speakeasy. Safe from regeneration.
 *
 * @see docs/REGENERATION.md
 */

declare(strict_types=1);

namespace Factuarea\Sdk\Custom\Request;

/**
 * Per-call overrides that the generated request models cannot express.
 *
 * Two gaps of the generated models are covered here:
 *
 * - Field presence. Every optional property is generated with `SkipWhenNull`,
 *   so an unassigned field and a field assigned `null` both travel omitted and
 *   the API's "null clears the value" contract is unreachable (see
 *   `Tests/Custom/Request/PresenceWireTest.php`). {@see self::run()} lists the
 *   fields to send as an explicit JSON `null`. Presence is never inferred: only
 *   the paths the caller names are written.
 * - Headers the spec does not declare yet (for example `If-Match`).
 *
 * The overrides are applied by {@see RequestOverridesClient} to every request
 * issued inside the callback, retries included, so the callback must contain a
 * single SDK call.
 *
 * ```php
 * RequestOverrides::run(
 *     fn () => $sdk->series->publicApiV1SeriesUpdate(new PublicApiV1SeriesUpdateRequest(
 *         company: $companyId,
 *         series: $id,
 *         body: new UpdateSeriesRequest(name: 'B2B'),
 *     )),
 *     clear: ['pdf_template_id'],
 *     headers: ['If-Match' => $etag],
 * );
 * ```
 */
final class RequestOverrides
{
    /** @var list<array{clear: list<string>, headers: array<string, string>}> */
    private static array $stack = [];

    /**
     * @template T
     *
     * @param  callable(): T  $call
     * @param  list<string>  $clear  JSON paths (dot-separated for nested objects, e.g. `identity.logo_id`) sent as `null`.
     * @param  array<string, string>  $headers  Extra request headers; they replace any header of the same name.
     * @return T
     */
    public static function run(callable $call, array $clear = [], array $headers = []): mixed
    {
        foreach ($clear as $path) {
            if ($path === '' || str_contains($path, '..') || str_starts_with($path, '.') || str_ends_with($path, '.')) {
                throw new \InvalidArgumentException(sprintf('Invalid JSON path to clear: "%s".', $path));
            }
        }

        self::$stack[] = ['clear' => $clear, 'headers' => $headers];

        try {
            return $call();
        } finally {
            array_pop(self::$stack);
        }
    }

    /**
     * @return ?array{clear: list<string>, headers: array<string, string>}
     */
    public static function current(): ?array
    {
        return self::$stack === [] ? null : self::$stack[array_key_last(self::$stack)];
    }
}
